mapper.select:
select
con.Con_Name as conName, con.Con_Code as conCode, con.Con_Money_Total as conMoneyTotal, dco.Dco_Major as dcoMajor, dco.Dco_Name as dcoName, dco.Dco_Code as dcoCode, dco.Dco_Project_Name as dcoProjectName, dco.Dco_Sub_Code as dcoSubCode, c1.C_Name as dcbSupervisorName, c2.C_Name as dcbContractorName, mn.* from Con_Dc_Budget mn left join Con_Dco dco on dco.Dco_Id=mn.Dco_Id left join Con_Contract con on con.Con_Id=mn.Con_Id left join Sys_Company c1 on c1.C_Id=mn.Dcb_Supervisor_Id left join Sys_Company c2 on c2.C_Id=mn.Dcb_Contractor_Id
${params.authSql}
and mn.Te_Id = #{params.teId}
and mn.P_Id=#{params.pId}
and mn.Dcb_Type=#{params.dcbType}
and dco.Dco_Major like concat('%',#{params.dcoMajor},'%')
and likePname(#{params.pName},mn.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
and dco.Dco_Name like concat('%',#{params.dcoName},'%')
and dco.Dco_Code like concat('%',#{params.dcoCode},'%')
and dco.Dco_Project_Name like concat('%',#{params.dcoProjectName},'%')
and dco.Dco_Sub_Code like concat('%',#{params.dcoSubCode},'%')
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Dcb_Create_Time desc
